// FactIntakes — one row per ANALYTIC intake event (exact duplicate rows excluded).
// Source  : RepoRoot & "data\processed\intakes_clean.csv"  (generated by analysis/audit_datasets.py)
// Grain   : intake_event_id (primary key, unique)
// Expected: 173,776 rows (173,812 source rows - 36 exact duplicate excess copies; DECISION_LOG D-009)
// Rules   : UTF-8; ISO dates/datetimes parsed with an explicit format (no locale guessing);
//           timestamps are source-local wall clock and are NOT timezone-converted (D-008);
//           flags 1/0 -> true/false; blank text -> null.
let
    SourcePath = RepoRoot & "data\processed\intakes_clean.csv",
    Raw = Csv.Document(File.Contents(SourcePath), [Delimiter = ",", Encoding = 65001, QuoteStyle = QuoteStyle.Csv]),
    Promoted = Table.PromoteHeaders(Raw, [PromoteAllScalars = false]),

    // Fail fast if the source schema changes; also fixes column order.
    ExpectedColumns = {
        "intake_event_id", "source_row", "animal_id", "intake_datetime", "intake_date", "monthyear_consistent",
        "name", "name_has_asterisk", "found_location", "intake_type", "intake_condition", "animal_type",
        "sex_upon_intake", "age_upon_intake_raw", "age_upon_intake_days", "age_upon_intake_invalid",
        "age_band_intake", "breed", "breed_is_mix", "color", "is_exact_duplicate", "is_same_id_timestamp_conflict"},
    Selected = Table.SelectColumns(Promoted, ExpectedColumns, MissingField.Error),

    // Blank strings -> null for every column before typing.
    BlankToNull = Table.TransformColumns(Selected, {}, each if _ = "" then null else _),

    // Locale-independent parsers for the ISO formats written by the Python pipeline.
    ParseDate = (t as nullable text) as nullable date =>
        if t = null then null else Date.FromText(t, [Format = "yyyy-MM-dd", Culture = "en-US"]),
    ParseDateTime = (t as nullable text) as nullable datetime =>
        if t = null then null else DateTime.FromText(t, [Format = "yyyy-MM-dd HH:mm:ss", Culture = "en-US"]),
    ParseNumber = (t as nullable text) as nullable number =>
        if t = null then null else Number.FromText(t, "en-US"),
    ParseInt = (t as nullable text) as nullable number =>
        if t = null then null else Int64.From(Number.FromText(t, "en-US")),
    ParseFlag = (t as nullable text) as nullable logical =>
        if t = null then null else if t = "1" then true else if t = "0" then false
        else error Error.Record("InvalidFlag", "Expected 1/0 flag value", t),

    TextColumns = {
        "intake_event_id", "animal_id", "name", "found_location", "intake_type", "intake_condition",
        "animal_type", "sex_upon_intake", "age_upon_intake_raw", "age_band_intake", "breed", "color"},
    TypedText = Table.TransformColumnTypes(BlankToNull, List.Transform(TextColumns, each {_, type text})),

    Typed = Table.TransformColumns(TypedText, {
        {"source_row", ParseInt, Int64.Type},
        {"intake_datetime", ParseDateTime, type nullable datetime},
        {"intake_date", ParseDate, type nullable date},
        {"age_upon_intake_days", ParseNumber, type nullable number},
        {"monthyear_consistent", ParseFlag, type nullable logical},
        {"name_has_asterisk", ParseFlag, type nullable logical},
        {"age_upon_intake_invalid", ParseFlag, type nullable logical},
        {"breed_is_mix", ParseFlag, type nullable logical},
        {"is_exact_duplicate", ParseFlag, type nullable logical},
        {"is_same_id_timestamp_conflict", ParseFlag, type nullable logical}}),

    // Analytic events only: exclude the excess copies of exact duplicate rows (D-009).
    AnalyticEvents = Table.SelectRows(Typed, each [is_exact_duplicate] = false),

    // Declare the key for the engine (does not change data).
    Keyed = Table.AddKey(AnalyticEvents, {"intake_event_id"}, true)
in
    Keyed
